<?php $delivered=(int)Db::scalar("SELECT COALESCE(SUM(quantity_g),0) FROM orders WHERE status='delivered'");$revenue=(int)Db::scalar('SELECT COALESCE(SUM(credit-debit),0) FROM journal_lines WHERE account_id=4010');$expense=(int)Db::scalar('SELECT COALESCE(SUM(debit-credit),0) FROM journal_lines WHERE account_id=5010');$jobs=Db::one('SELECT COALESCE(SUM(input_g),0) AS input_g,COALESCE(SUM(output_g),0) AS output_g FROM production_jobs');$months=Db::all("SELECT DATE_FORMAT(created_at,'%Y-%m') AS month,SUM(quantity_g) AS grams FROM orders WHERE status='delivered' AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 6 MONTH) GROUP BY DATE_FORMAT(created_at,'%Y-%m') ORDER BY month"); ?>
